def to_stream(iter) do
  Stream.resource(
    fn -> iter end,
    fn iter ->
      case Iterable.next(iter.iterable) do
        {:ok, element, iterable} -> {[element], %{iter | iterable: iterable}}
        :done -> {:halt, iter}
      end
    end,
    fn _ -> :ok end
  )
end

def repeatedly(generator_fun) when is_function(generator_fun, 0) do
  resource(
    fn -> nil end,
    fn _ -> {[generator_fun.()], nil} end,
    fn _ -> nil end
  )
end

