    {:alias, charlist}
    | {:alias, inside_alias, charlist}
    | {:dot, inside_dot, charlist}
    | {:local_or_var, charlist}
    | {:local_arity, charlist}
    | {:local_call, charlist}
    | {:module_attribute, charlist}
    | {:operator, charlist}
    | {:sigil, charlist}
    | {:struct, inside_struct}
    | {:unquoted_atom, charlist}
    | {:keyword, charlist}
    | {:key, charlist}
    | {:capture_arg, charlist},
  inside_dot:
    {:alias, charlist}
    | {:alias, inside_alias, charlist}
    | {:dot, inside_dot, charlist}
    | {:module_attribute, charlist}
    | {:unquoted_atom, charlist}
    | {:var, charlist}
    | :expr,
  inside_alias: {:local_or_var, charlist} | {:module_attribute, charlist},
  inside_struct:
    charlist
    | {:alias, inside_alias, charlist}
    | {:local_or_var, charlist}
    | {:module_attribute, charlist}
    | {:dot, inside_dot, charlist}
]

definition:
def unary_op(op) do
  cond do
    op in [:&, :...] -> {:non_associative, 90}
    op in [:!, :^, :not, :+, :-, :"~~~"] -> {:non_associative, 300}
    op in [:@] -> {:non_associative, 320}
    true -> :error
  end
end

