def pairs_to_ranges(pairs) do
  pairs
  |> Enum.map(fn {{r1, _}, {r2, _}} ->
    %GenLSP.Structures.FoldingRange{
      start_line: r1,
      end_line: r2 - 1,
      kind: GenLSP.Enumerations.FoldingRangeKind.region()
    }
  end)
end

