def handle_sqs_results(
      {:error,
       {:http_error, http_status, %{code: code, message: message, request_id: request_id}}}
    ) do
  Logger.error(
    "SQS request HTTP error: http_status=#{http_status} code=#{code}, message=#{message}, request_id=#{request_id}"
  )

  {:ok, []}
end
def handle_sqs_results({:error, error}) do
