def get_name() do
  Agent.get_and_update(__MODULE__, fn state ->
    {name, q, seq_num} =
      case state.q |> Qex.pop() do
        {{:value, v}, q} -> {v, q, state.seq_num}
        {:empty, q} -> {:"bundlex_cnode_#{state.seq_num}_#{state.self_id}", q, state.seq_num + 1}
      end

    {{name, state.creations |> Map.get(name, 0)}, %{state | seq_num: seq_num, q: q}}
  end)
end

