  with [id_direction, uri_attributes] <- String.split(extmap, " ", parts: 2),
       {:ok, {id, direction}} <- parse_id_direction(id_direction),
       {:ok, {uri, attributes}} <- parse_uri_attributes(uri_attributes) do
